const antibiotics = /\b(amoxicillin|ampicillin|ceftiofur|ceftriaxone|cephalexin|chlortetracycline|doxycycline|enrofloxacin|erythromycin|florfenicol|gentamicin|lincomycin|neomycin|oxytetracycline|penicillin|streptomycin|sulfamethazine|sulfadiazine|tetracycline|tilmicosin|trimethoprim|tylosin|tulathromycin|antibiotic|antimicrobial)\b/i;
