const FieldChangeContext = createContext<(name: string, value: string) => void>(() => undefined);
const AnimalContext = createContext<Animal | null>(null);

function Field({ label, name, value, type = "text", required = false, options }: { label: string; name: string; value: string; type?: string; required?: boolean; options?: string[] }) {
  const onChange = useContext(FieldChangeContext);
  return <label className="field">{label}{options ? <select required={required} value={value} onChange={(event) => onChange(name, event.target.value)}>{options.map((option) => <option key={option} value={option}>{option || "Select"}</option>)}</select> : <input required={required} type={type} step={type === "number" ? "0.01" : undefined} min={type === "number" ? "0.01" : undefined} value={value} onChange={(event) => onChange(name, event.target.value)}/>}</label>;
}

function Fact({ label, field, suffix = "", wide = false }: { label: string; field: string; suffix?: string; wide?: boolean }) {
  const animal = useContext(AnimalContext);
  const value = animal?.[field];
  const display = value === true ? "Yes" : value === false ? "No" : value == null || value === "" ? "-" : `${String(value).slice(0, field.endsWith("date") ? 10 : undefined)}${suffix}`;
  return <div className={wide ? "profile-fact-wide" : undefined}><dt>{label}</dt><dd>{field === "purchase_price" && value ? new Intl.NumberFormat("en-PH", { style: "currency", currency: "PHP" }).format(Number(value)) : display}</dd></div>;
}

